#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <ctype.h>

#define MAX_URL_LEN 2048
#define MAX_NODES 16
#define CACHE_PORT 11211

typedef struct {
    char host[256];
    int port;
    int weight;
    char health_endpoint[512];
} cache_node_t;

typedef struct {
    cache_node_t nodes[MAX_NODES];
    int node_count;
    char service_discovery_url[MAX_URL_LEN];
    char redirect_base[MAX_URL_LEN];
} cache_cluster_t;

static int is_safe_scheme(const char *url) {
    if (strncasecmp(url, "http://", 7) == 0) return 1;
    if (strncasecmp(url, "https://", 8) == 0) return 1;
    return 0;
}

static int validate_internal_redirect(const char *url, const char *allowed_domain) {
    const char *host_start;
    char extracted_host[256];
    int i = 0;

    if (!is_safe_scheme(url)) return 0;

    /* Skip past scheme */
    host_start = strstr(url, "://");
    if (!host_start) return 0;
    host_start += 3;

    /* Reject any URL with userinfo (@ before first /) to prevent authority confusion */
    const char *slash = strchr(host_start, '/');
    const char *at_sign = strchr(host_start, '@');
    if (at_sign && (!slash || at_sign < slash)) {
        return 0; /* Reject URLs with userinfo component */
    }

    /* Extract host component */
    while (host_start[i] && host_start[i] != '/' && host_start[i] != ':' && host_start[i] != '?' && i < 255) {
        extracted_host[i] = tolower((unsigned char)host_start[i]);
        i++;
    }
    extracted_host[i] = '\0';

    /* Reject empty host */
    if (i == 0) return 0;

    /* Check if extracted host ends with allowed_domain */
    size_t host_len = strlen(extracted_host);
    size_t domain_len = strlen(allowed_domain);
    if (host_len < domain_len) return 0;

    /* Suffix match: host must end with .allowed_domain or equal allowed_domain */
    if (strcmp(extracted_host + host_len - domain_len, allowed_domain) == 0) {
        if (host_len == domain_len) return 1;
        if (extracted_host[host_len - domain_len - 1] == '.') return 1;
    }
    return 0;
}

static int resolve_cache_redirect(cache_cluster_t *cluster, const char *location_header, char *resolved_url, size_t resolved_len) {
    char normalized[MAX_URL_LEN];

    if (!location_header || strlen(location_header) == 0) return -1;

    /* Handle relative redirects by prepending base */
    if (location_header[0] == '/') {
        snprintf(normalized, sizeof(normalized), "%s%s", cluster->redirect_base, location_header);
    } else {
        strncpy(normalized, location_header, sizeof(normalized) - 1);
        normalized[sizeof(normalized) - 1] = '\0';
    }

    /* Validate the redirect target is within our cluster domain */
    if (!validate_internal_redirect(normalized, "cache.internal.svc.cluster.local")) {
        fprintf(stderr, "[security] Blocked redirect to external host: %s\n", normalized);
        return -1;
    }

    strncpy(resolved_url, normalized, resolved_len - 1);
    resolved_url[resolved_len - 1] = '\0';
    return 0;
}

static int follow_service_discovery(cache_cluster_t *cluster, const char *initial_url, char *final_url, size_t final_len) {
    char current_url[MAX_URL_LEN];
    char next_url[MAX_URL_LEN];
    int hops = 0;
    const int max_hops = 5;

    strncpy(current_url, initial_url, sizeof(current_url) - 1);
    current_url[sizeof(current_url) - 1] = '\0';

    while (hops < max_hops) {
        /* Simulate receiving a redirect from the service mesh */
        char simulated_location[MAX_URL_LEN];

        /* The k8s service mesh may return a redirect with the actual pod endpoint */
        const char *query = strchr(current_url, '?');
        if (query) {
            const char *next_param = strstr(query, "next=");
            if (next_param) {
                next_param += 5; /* skip 'next=' */
                /* URL-decode the next parameter in-place */
                int si = 0, di = 0;
                while (next_param[si] && next_param[si] != '&' && di < MAX_URL_LEN - 1) {
                    if (next_param[si] == '%' && isxdigit((unsigned char)next_param[si+1]) && isxdigit((unsigned char)next_param[si+2])) {
                        char hex[3] = {next_param[si+1], next_param[si+2], 0};
                        simulated_location[di++] = (char)strtol(hex, NULL, 16);
                        si += 3;
                    } else {
                        simulated_location[di++] = next_param[si++];
                    }
                }
                simulated_location[di] = '\0';
            } else {
                break;
            }
        } else {
            break;
        }

        if (resolve_cache_redirect(cluster, simulated_location, next_url, sizeof(next_url)) != 0) {
            return -1; /* Blocked */
        }

        strncpy(current_url, next_url, sizeof(current_url) - 1);
        current_url[sizeof(current_url) - 1] = '\0';
        hops++;
    }

    strncpy(final_url, current_url, final_len - 1);
    final_url[final_len - 1] = '\0';
    return 0;
}

int cache_client_connect(cache_cluster_t *cluster, const char *discovery_url) {
    char resolved_endpoint[MAX_URL_LEN];

    strncpy(cluster->redirect_base, "https://cache.internal.svc.cluster.local", sizeof(cluster->redirect_base) - 1);
    cluster->redirect_base[sizeof(cluster->redirect_base) - 1] = '\0';
    strncpy(cluster->service_discovery_url, discovery_url, sizeof(cluster->service_discovery_url) - 1);
    cluster->service_discovery_url[sizeof(cluster->service_discovery_url) - 1] = '\0';

    if (follow_service_discovery(cluster, discovery_url, resolved_endpoint, sizeof(resolved_endpoint)) != 0) {
        fprintf(stderr, "Service discovery failed\n");
        return -1;
    }

    printf("[cache_client] Connecting to resolved endpoint: %s\n", resolved_endpoint);
    /* In production: establish TCP connection to the resolved cache node */
    return 0;
}

int main(int argc, char *argv[]) {
    cache_cluster_t cluster;
    memset(&cluster, 0, sizeof(cluster));

    const char *discovery_url = argc > 1 ? argv[1] :
        "https://cache.internal.svc.cluster.local/discover?next=https%3A%2F%2Fcache.internal.svc.cluster.local%2Fnode1";

    return cache_client_connect(&cluster, discovery_url);
}
